CREATE TABLE "TimelineEvent" ("id" TEXT NOT NULL PRIMARY KEY,"profileId" TEXT NOT NULL,"kind" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"importBatchId" TEXT,"transactionId" TEXT,"transactionRevisionId" TEXT,"reconciliationDecisionId" TEXT,"reversible" BOOLEAN NOT NULL DEFAULT false,"revertedAt" DATETIME,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "TimelineEvent_profileId_fkey" FOREIGN KEY ("profileId") REFERENCES "LocalProfile" ("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "TimelineEvent_importBatchId_fkey" FOREIGN KEY ("importBatchId") REFERENCES "ImportBatch" ("id") ON DELETE SET NULL ON UPDATE CASCADE,CONSTRAINT "TimelineEvent_transactionId_fkey" FOREIGN KEY ("transactionId") REFERENCES "Transaction" ("id") ON DELETE SET NULL ON UPDATE CASCADE,CONSTRAINT "TimelineEvent_transactionRevisionId_fkey" FOREIGN KEY ("transactionRevisionId") REFERENCES "TransactionRevision" ("id") ON DELETE SET NULL ON UPDATE CASCADE,CONSTRAINT "TimelineEvent_reconciliationDecisionId_fkey" FOREIGN KEY ("reconciliationDecisionId") REFERENCES "ReconciliationDecision" ("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE "DatabaseBackup" ("id" TEXT NOT NULL PRIMARY KEY,"profileId" TEXT NOT NULL,"schemaVersion" TEXT NOT NULL,"checksum" TEXT NOT NULL,"byteSize" INTEGER NOT NULL,"status" TEXT NOT NULL,"verifiedAt" DATETIME,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "DatabaseBackup_profileId_fkey" FOREIGN KEY ("profileId") REFERENCES "LocalProfile" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "TimelineEvent_profileId_createdAt_idx" ON "TimelineEvent"("profileId","createdAt");
CREATE INDEX "TimelineEvent_importBatchId_idx" ON "TimelineEvent"("importBatchId");
CREATE INDEX "TimelineEvent_transactionId_idx" ON "TimelineEvent"("transactionId");
CREATE INDEX "DatabaseBackup_profileId_createdAt_idx" ON "DatabaseBackup"("profileId","createdAt");
CREATE INDEX "DatabaseBackup_profileId_status_verifiedAt_idx" ON "DatabaseBackup"("profileId","status","verifiedAt");
